  "est_desc_home_prama": "घने अंधेरे में भी 24/7 साफ रंगीन रिकॉर्डिंग। पूरी तरह BIS-ER सर्टिफाइड भारतीय ब्रांड।",
  "est_desc_office_cp": "रिसेप्शन, केबिन, स्टाफ डेस्क, सर्वर रूम और एंट्री गेट की पूरी देखरेख।",
  "est_desc_office_hik": "कमर्शियल लेवल की क्लैरिटी, माइक से ऑडियो सपोर्ट और एक साथ कई फोन/डेस्कटॉप पर लाइव व्यू।",
  "est_desc_office_prama": "ऑफिस कॉरिडोर, गोदाम, यार्ड और फैक्ट्री के लिए हेवी-ड्यूटी 24/7 कलर नाइट देखरेख।",
  "est_desc_shop_cp": "बिलिंग काउंटर, रैक, गोदाम और दुकान के शटर की पूरी देखरेख।",
  "est_desc_shop_hik": "काउंटर पर नोटों की गिनती, ग्राहक की साफ पहचान और माइक से आवाज़ भी रिकॉर्ड होती है।",
  "est_desc_shop_prama": "रात में शटर बंद होने के बाद भी दिन जैसी रंगीन फुटेज — दुकान की सुरक्षा के लिए बेहतरीन।",
